SELECT COUNT(DISTINCT mp.subject_id) AS male_patient_cohort_size, percentile_cont(0.0) within GROUP (ORDER BY mp.subject_id) AS min_subject_id, percentile_cont(0.25) within GROUP (ORDER BY mp.subject_id) AS percentile_25th_subject_id, percentile_cont(0.75) within GROUP (ORDER BY mp.subject_id) AS percentile_75th_subject_id, percentile_cont(1.0) within GROUP (ORDER BY mp.subject_id) AS max_subject_id, SUM(CASE WHEN mp.subject_id IN (SELECT d.subject_id FROM deaths d) THEN 1 ELSE 0 END) AS deaths_among_patients, SUM(CASE WHEN mp.subject_id IN (SELECT s.subject_id FROM sepsis s) THEN 1 ELSE 0 END) AS sepsis_among_patients, SUM(CASE WHEN mp.subject_id IN (SELECT s.subject_id FROM acute_resp_distress s) THEN 1 ELSE 0 END) AS ards_among_patients, AVG(s.los) AS average_length_of_stay FROM male_patients mp UNION ALL SELECT COUNT(DISTINCT mip.subject_id) AS male_icu_patient_cohort_size, percentile_cont(0.0) within GROUP (ORDER BY mip.subject_id) AS min_subject_icu_id, percentile_cont(0.25) within GROUP (ORDER BY mip.subject_id) AS percentile_25th_subject_icu_id, percentile_cont(0.75) within GROUP (ORDER BY mip.subject_id) AS percentile_75th_subject_icu_id, percentile_cont(1.0) within GROUP (ORDER BY mip.subject_id) AS max_subject_icu_id, SUM(CASE WHEN mip.subject_id IN (SELECT d.subject_id FROM deaths d) THEN 1 ELSE 0 END) AS deaths_among_icu_patients, SUM(CASE WHEN mip.subject_id IN (SELECT s.subject_id FROM sepsis s) THEN 1 ELSE 0 END) AS sepsis_among_icu_patients, SUM(CASE WHEN mip.subject_id IN (SELECT s.subject_id FROM acute_resp_distress s) THEN 1 ELSE 0 END) AS ards_among_icu_patients, AVG(s.los) AS average_length_of_stay_in_icu FROM male_icu_patients mip;